import React from 'react';

/** Props meant to be used in child nodes, such as Pagination. */
export interface PaginationContextProps {
  /** The index of the current page. */
  pageIndex: number;
  /** The total number of pages. */
  pageCount: number;
  /** The page size that react-table holds. */
  pageSize?: number;
  /** Whether the previous page is available (if not, the 'go to previous page' button should be disabled).	*/
  canPreviousPage: boolean;
  /** Whether the next page is available (if not, the 'go to next page' button should be disabled).*/
  canNextPage: boolean;
  /** Whether manual pagination is enabled and rows need to be paginated.*/
  manualPagination: boolean;
  /** The table rows */
  data: any[]; // eslint-disable-line @typescript-eslint/no-explicit-any
  /** Callback used for navigating to a page with a given index. The pageIndex will be set to that value, if valid. */
  setPageIndex: (pageIndex?: number) => void;
  /** Callback used for setting the page size. */
  setPageSize: (pageSize?: number) => void;
}

/** Context provider for `TablePaginationContext` props meant to be provided to all its child nodes. */
export const TablePaginationContext =
  React.createContext<PaginationContextProps>({
    canPreviousPage: true,
    canNextPage: true,
    pageIndex: 0,
    pageSize: undefined,
    pageCount: 0,
    setPageIndex: () => null,
    setPageSize: () => null,
    manualPagination: false,
    data: [],
  });
